// Phase 5: one self-checking testbench for all three row checkers.
// Reads vectors (generated by src/hw_vectors.py from the Python models) for one row size,
// applies each to parity, CRC-8 and SECDED, compares every output, prints PASS/FAIL.
// Usage: vvp sim +DIR=hw/vectors +NB=8   (or +NB=2)
`timescale 1ns/1ps
module tb_row_checkers;
    parameter N_BYTES = 8;
    parameter R       = 7;
    localparam W  = 8 * N_BYTES;
    localparam WP = W + 3;
    localparam WC = W + 17;
    localparam WS = 2 * W + 2 * R + 4;
    localparam MAXV = 8192;

    reg [WP-1:0] vp [0:MAXV-1];
    reg [WC-1:0] vc [0:MAXV-1];
    reg [WS-1:0] vs [0:MAXV-1];

    reg  [W-1:0] row_p, row_c, row_s;
    reg          st_p;
    reg  [7:0]   st_c;
    reg  [R:0]   st_s;
    wire         code_p, ok_p, ok_c;
    wire [7:0]   code_c;
    wire [W-1:0] fixed_s;
    wire [1:0]   status_s;
    wire [R:0]   code_s;

    row_parity #(.N_BYTES(N_BYTES))       u_p (.row(row_p), .stored(st_p), .code(code_p), .ok(ok_p));
    row_crc8   #(.N_BYTES(N_BYTES))       u_c (.row(row_c), .stored(st_c), .code(code_c), .ok(ok_c));
    row_secded #(.N_BYTES(N_BYTES), .R(R)) u_s (.row(row_s), .stored(st_s), .fixed(fixed_s),
                                                .status(status_s), .code(code_s));

    reg [8*256-1:0] dir;
    reg [8*300-1:0] fp, fc, fs;
    integer i, n, errors, fd;
    reg [WP-1:0] a; reg [WC-1:0] b; reg [WS-1:0] c;

    initial begin
        if (!$value$plusargs("DIR=%s", dir)) dir = "hw/vectors";
        $sformat(fp, "%0s/parity_%0dB.hex", dir, N_BYTES);
        $sformat(fc, "%0s/crc8_%0dB.hex", dir, N_BYTES);
        $sformat(fs, "%0s/secded_%0dB.hex", dir, N_BYTES);
        for (i = 0; i < MAXV; i = i + 1) begin vp[i] = {WP{1'bx}}; vc[i] = {WC{1'bx}}; vs[i] = {WS{1'bx}}; end
        $readmemh(fp, vp);
        $readmemh(fc, vc);
        $readmemh(fs, vs);
        errors = 0;
        n = 0;
        for (i = 0; i < MAXV && vp[i][0] !== 1'bx; i = i + 1) begin
            a = vp[i]; b = vc[i]; c = vs[i];
            {row_p, st_p} = a[WP-1:2];
            {row_c, st_c} = b[WC-1:9];
            row_s = c[WS-1 -: W];
            st_s  = c[WS-1-W -: R+1];
            #1;
            if (code_p !== a[1] || ok_p !== a[0]) begin
                errors = errors + 1;
                $display("FAIL parity vec %0d: got code=%b ok=%b", i, code_p, ok_p);
            end
            if (code_c !== b[8:1] || ok_c !== b[0]) begin
                errors = errors + 1;
                $display("FAIL crc8 vec %0d: got code=%h ok=%b exp %h %b", i, code_c, ok_c, b[8:1], b[0]);
            end
            if (fixed_s !== c[R+2+W : R+3] || status_s !== c[R+2:R+1] || code_s !== c[R:0]) begin
                errors = errors + 1;
                $display("FAIL secded vec %0d: status=%0d exp %0d", i, status_s, c[R+2:R+1]);
            end
            n = n + 1;
        end
        if (n == 0) begin
            $display("FAIL: no vectors read from %0s", fp);
            errors = 1;
        end
        if (errors == 0) $display("PASS: %0d vectors x 3 checkers, %0d-byte rows", n, N_BYTES);
        else             $display("FAIL: %0d errors in %0d vectors, %0d-byte rows", errors, n, N_BYTES);
        $finish;
    end
endmodule
